import{_ as t,o as a,c as r,a2 as n}from"./chunks/framework.CdjpmwdR.js";const p=JSON.parse(`{"title":"Container Ecosystem in Motion: Docker, containerd, runc and Kubernetes","description":"Timeline of Docker's rise, OCI runtime standardization, and Kubernetes runtime shifts, clarifying relationships between dockerd, containerd, runc, CRI, and OCI.","frontmatter":{"category":"node","date":"2022-05-01","title":"Container Ecosystem in Motion: Docker, containerd, runc and Kubernetes","description":"Timeline of Docker's rise, OCI runtime standardization, and Kubernetes runtime shifts, clarifying relationships between dockerd, containerd, runc, CRI, and OCI.","tags":["node","K8s"],"image":"https://pic2.zhimg.com/v2-8eab1606a489aa28545ed7f984f80b01.jpg"},"headers":[],"relativePath":"en/blogs/2022/202205-container-k8s-docker.md","filePath":"en/blogs/2022/202205-container-k8s-docker.md"}`),o={name:"en/blogs/2022/202205-container-k8s-docker.md"};function i(s,e,c,d,l,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<p><img src="https://pic2.zhimg.com/v2-8eab1606a489aa28545ed7f984f80b01.jpg" alt=""></p><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to &quot;Background&quot;">​</a></h2><p>When I started to learn Kubernetes systematically this year, I noticed that Kubernetes introduced multiple interfaces and standards to better modularize the system and support various cloud platforms and runtimes. At the same time, Docker support was removed in favor of containerd as the default container runtime.</p><p>To understand the story behind these changes, I drew a landscape diagram and connected the dots among the key technologies.</p><p><em>(Most of the information is already in the diagram; the text here mainly acts as a guided tour.)</em><br><em>(This is based on my understanding — please cross‑check with official docs.)</em></p><h2 id="docker-enters-the-stage" tabindex="-1">Docker Enters the Stage <a class="header-anchor" href="#docker-enters-the-stage" aria-label="Permalink to &quot;Docker Enters the Stage&quot;">​</a></h2><p><img src="https://pic3.zhimg.com/v2-2e5bff692825013e0537ec33fc1bde8e_b.jpg" alt=""></p><p>Docker did not invent <code>namespace</code> or <code>cgroup</code>, but wrapped these kernel features into a workflow that developers could use directly. What truly changed the ecosystem was the layered image model and delivery experience: code, dependencies, and runtime are packed into reproducible units.</p><p><img src="https://pic2.zhimg.com/v2-23eda6e9882ef84ac4f92543079b3f39_b.jpg" alt=""></p><p>Combined with a simple CLI and Docker Hub, containers moved from &quot;expert tooling&quot; to &quot;every team can actually use this in production&quot;.</p><h2 id="kubernetes-vs-docker-swarm" tabindex="-1">Kubernetes vs Docker Swarm <a class="header-anchor" href="#kubernetes-vs-docker-swarm" aria-label="Permalink to &quot;Kubernetes vs Docker Swarm&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/v2-ec7c2c677631f7fcb616166676501d43_b.jpg" alt=""></p><p>After Docker unified single‑host container workflows, it naturally tried to move up the stack into PaaS and orchestration — which is where cloud vendors make serious money.</p><p>Around 2014 two events changed Docker&#39;s destiny:</p><ul><li><strong>Kubernetes</strong> appeared with the Google halo and quickly captured developer mindshare.</li><li><strong>OCI (Open Container Initiative)</strong> was founded (led by Google, Red Hat, etc.) to define container standards.</li></ul><p>Docker started splitting its components and implementing these standards to integrate with different platforms. <code>runc</code> and <code>containerd</code> became popular building blocks in the wider ecosystem, while &quot;Docker&quot; the product gradually faded into &quot;docker&quot; the generic word for containers.</p><p><em>(If Docker had not joined OCI, not donated runc, what would the ecosystem look like today?)</em><br> _(Recently Istio finally joined CNCF as well...)</p><h2 id="oci-open-container-initiative" tabindex="-1">OCI: Open Container Initiative <a class="header-anchor" href="#oci-open-container-initiative" aria-label="Permalink to &quot;OCI: Open Container Initiative&quot;">​</a></h2><p><img src="https://pic4.zhimg.com/v2-505c8cfaeac6e5042330af60890c9813_b.jpg" alt=""></p><p>Under the Linux Foundation, OCI defines the <strong>Runtime</strong> and <strong>Image</strong> specifications so users can choose different container runtimes based on needs: hypervisor‑based Kata Containers for strong isolation, syscall‑intercepting gVisor, and so on.</p><p>When people say &quot;OCI runtime&quot; they usually mean the low‑level component that actually creates containers and manages images according to these specs.</p><h2 id="kubernetes-takes-the-high-ground" tabindex="-1">Kubernetes Takes the High Ground <a class="header-anchor" href="#kubernetes-takes-the-high-ground" aria-label="Permalink to &quot;Kubernetes Takes the High Ground&quot;">​</a></h2><p><img src="https://pic2.zhimg.com/v2-98750bc5070732faf351a1e71fd8d7a9_b.jpg" alt=""></p><p>Kubernetes used open source momentum to attract developers, developers influenced technical decisions, and over time Kubernetes won the orchestration war. Today it is the de facto standard. Even PaaS platforms that pre‑dated containers (AWS, Cloud Foundry, etc.) are getting eaten by Kubernetes‑based offerings.</p><p>Kubernetes is essentially a PaaS. To integrate with different implementations — container runtimes, networking, storage, cloud services — it defines a set of interfaces: CRI, CNI, CSI, CCM, etc.</p><p>The later removal of dockershim was not &quot;abandoning Docker&quot;; it was about clarifying boundaries. Kubernetes needs a CRI‑compliant runtime, not the full Docker UX stack. <code>containerd</code> is a better fit as a focused runtime.</p><h2 id="container-runtime" tabindex="-1">&quot;Container Runtime&quot; <a class="header-anchor" href="#container-runtime" aria-label="Permalink to &quot;&quot;Container Runtime&quot;&quot;">​</a></h2><p>You will often see two layers of runtimes:</p><ul><li><strong>CRI runtimes</strong>: used by Kubernetes to manage Pods — multi‑container units that share network and storage.</li><li><strong>OCI runtimes</strong>: used to talk directly to the kernel to create containers.</li></ul><p>A common distinction is:</p><ul><li><code>containerd</code> and similar are <strong>high‑level runtimes</strong>, closer to orchestration platforms.</li><li><code>runc</code> is a <strong>low‑level runtime</strong>, closer to raw kernel primitives.</li></ul><h2 id="what-is-a-shim" tabindex="-1">What Is a Shim? <a class="header-anchor" href="#what-is-a-shim" aria-label="Permalink to &quot;What Is a Shim?&quot;">​</a></h2><p>&quot;Shim&quot; is another overloaded term. Literally it means a small spacer or adapter layer, and you will see it used in different contexts.</p><p><img src="https://pic2.zhimg.com/v2-c48f1605cadaf38cb90e1222da20aa51_b.jpg" alt=""></p><p>In <strong>Docker&#39;s</strong> context, the shim is the layer between the manager (<code>containerd</code>) and the low‑level runtime (<code>runc</code>).</p><p><img src="https://pic3.zhimg.com/v2-556e53e5bd8477861db967326775af6e_b.jpg" alt=""></p><p>In <strong>Kubernetes</strong> docs, shim used to refer to the bridge between the CRI client (kubelet) and Docker/containerd.</p><blockquote><p>Initially Kubernetes only supported Docker, so it used dockershim as a bridge. With CRI‑containerd, this extra shim layer disappears.</p></blockquote><p><img src="https://pic1.zhimg.com/v2-6a94ea5611ac846c8064fc1b2998da30_b.jpg" alt=""></p><p>In <strong>containerd</strong> architecture docs, shim again refers to the layer between the OCI client (containerd) and the runtime (<code>runc</code>).</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li><a href="https://mp.weixin.qq.com/s?__biz=MzkzMTM1MDEyOA==&amp;mid=2247483673&amp;idx=1&amp;sn=405f481ab19f928bb85add017201fb1c" target="_blank" rel="noreferrer">9000字长文复盘Docker兴衰，从容器大战史推演基础软件投资</a></li><li><a href="https://kubernetes.io/zh-cn/blog/2022/05/03/dockershim-historical-context/" target="_blank" rel="noreferrer">Dockershim：历史背景</a></li><li>容器江湖的爱恨情仇 - Thoughtworks 中国文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/523574407" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/523574407</a></li><li><a href="https://mp.weixin.qq.com/s?__biz=MzI5ODQ2MzI3NQ==&amp;mid=2247507046&amp;idx=1&amp;sn=1c8f205730fb3b7b9519725b7d7730d0" target="_blank" rel="noreferrer">Kubernetes容器平台，从繁荣走向碎片化</a></li><li><a href="https://www.youtube.com/watch?v=BE77h7dmoQU" target="_blank" rel="noreferrer">Kubernetes: The Documentary [PART 1]</a></li><li><a href="https://www.youtube.com/watch?v=318elIq37PE" target="_blank" rel="noreferrer">Kubernetes: The Documentary [PART 2]</a></li><li><a href="https://mp.weixin.qq.com/s/GHjvvTJ8ZerIyCqXB1BSUQ" target="_blank" rel="noreferrer">K8s宣布弃用Docker，千万别慌！</a></li></ul>',42)])])}const m=t(o,[["render",i]]);export{p as __pageData,m as default};
